def num_decodings(s):
    def dfs(i):
        if i == len(s):
            return 1
        if s[i] == '0':
            return 0
        ways = dfs(i + 1)
        if i + 1 < len(s) and 10 <= int(s[i:i+2]) <= 26:
            ways += dfs(i + 2)
        return ways
    return dfs(0)

